<?php
session_start();require __DIR__ . '/../../config/db_connection.php';if(!isset($_SESSION['admin_id'])){header('Location:admin_login.php');exit;}ob_start(function($html){$extra='<style>.save{background:#2563eb!important;color:#fff!important;border:0!important;border-radius:8px!important;padding:9px 13px!important;box-shadow:0 3px 8px rgba(37,99,235,.18)!important;transition:.15s!important}.save:hover{background:#1d4ed8!important;transform:translateY(-1px)}.danger-action{background:#dc2626!important;box-shadow:0 3px 8px rgba(220,38,38,.16)!important}.restore-action{background:#16a34a!important;box-shadow:0 3px 8px rgba(22,163,74,.16)!important}.inventory-row:hover{background:#f8fafc}.card{border:1px solid #e8edf5!important}.selector select,table select,.stock{background:#fff!important;border:1px solid #cbd5e1!important;border-radius:8px!important}.section-note{display:inline-flex;align-items:center;background:#eff6ff;color:#1d4ed8;padding:5px 9px;border-radius:20px;font-size:12px;font-weight:600}</style><script>document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll("button.save").forEach(b=>{const t=b.textContent.trim().toLowerCase();if(t.includes("close"))b.classList.add("danger-action");if(t.includes("open")||t.includes("restore"))b.classList.add("restore-action");});document.querySelectorAll("tbody tr").forEach(r=>r.classList.add("inventory-row"));});</script>';$html=str_replace('</head>',$extra.'</head>',$html);return $html;});
echo '<style>.card.empty{padding:28px 30px!important;margin-top:6px!important;min-height:88px!important;display:flex!important;align-items:center!important;border-left:4px solid #bfdbfe!important;color:#475569!important}</style>';
function audit($c,$id,$text){$s=$c->prepare('INSERT INTO admin_audit_log(admin_id,action_text) VALUES(?,?)');$s->bind_param('is',$id,$text);$s->execute();$s->close();}
$selected=(int)($_REQUEST['canteen_id']??0);$message='';if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['food_id'])){$id=(int)$_POST['food_id'];$available=(int)$_POST['available'];$stock=max(0,(int)$_POST['stock_quantity']);$s=$conn->prepare('UPDATE foods SET is_available=?,stock_quantity=? WHERE id=?');$s->bind_param('iii',$available,$stock,$id);$s->execute();$s->close();audit($conn,$_SESSION['admin_id'],"Moderated food item #$id");$message='Food inventory updated.';}elseif(isset($_POST['operating_status'])){$active=(int)$_POST['operating_status'];$s=$conn->prepare('UPDATE canteens SET is_active=? WHERE id=?');$s->bind_param('ii',$active,$selected);$s->execute();$s->close();audit($conn,$_SESSION['admin_id'],"Changed operating status for canteen #$selected");$message='Canteen status updated.';}elseif(isset($_POST['title'])){$title=trim($_POST['title']);$body=trim($_POST['message']);if($title&&$body){$s=$conn->prepare('INSERT INTO announcements(title,message) VALUES(?,?)');$s->bind_param('ss',$title,$body);$s->execute();$s->close();audit($conn,$_SESSION['admin_id'],"Published announcement: $title");$message='Announcement published.';}}}
$canteens=$conn->query('SELECT id,canteen_name,is_active FROM canteens ORDER BY canteen_name');$selectedCanteen=null;if($selected){$s=$conn->prepare('SELECT id,canteen_name,is_active FROM canteens WHERE id=?');$s->bind_param('i',$selected);$s->execute();$selectedCanteen=$s->get_result()->fetch_assoc();$s->close();}$foods=null;if($selectedCanteen){$s=$conn->prepare('SELECT id,name,price,stock_quantity,is_available FROM foods WHERE canteen_id=? ORDER BY name');$s->bind_param('i',$selected);$s->execute();$foods=$s->get_result();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Operations & Moderation</title><link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@600;700&family=Poppins:wght@400;600&display=swap" rel="stylesheet"><style>:root{--blue:#2563eb;--muted:#64748b}*{box-sizing:border-box}body{margin:0;padding:24px;font-family:Poppins,sans-serif;background:#f1f5f9;color:#0f172a}.top,.card{background:#fff;border-radius:12px;box-shadow:0 2px 10px #0000000d}.top{padding:18px 22px;margin-bottom:18px}.top h1{font:700 21px Montserrat;margin:0}.top p{margin:5px 0 0;color:var(--muted);font-size:13px}.selector{display:flex;gap:9px;margin-top:15px}.selector select,.selector button,input,textarea{padding:9px;border:1px solid #cbd5e1;border-radius:7px;font:inherit}.selector select{min-width:280px}.selector button,.save{background:var(--blue);color:#fff;border:0;font-weight:600}.card{padding:18px;margin-bottom:18px;overflow:auto}.card h2{font:700 17px Montserrat;margin:0 0 6px}table{width:100%;border-collapse:collapse;min-width:650px}th,td{padding:10px 8px;text-align:left;border-bottom:1px solid #e2e8f0;font-size:13px}th{color:var(--muted);font-size:12px}.status{padding:4px 8px;border-radius:20px;background:#e2e8f0;font-size:12px}.open{color:#166534;background:#dcfce7}.closed{color:#b91c1c;background:#fee2e2}.notice{background:#dcfce7;color:#166534;padding:10px 13px;border-radius:8px;margin-bottom:14px}.stock{width:80px}textarea{width:100%;height:70px;display:block;margin:8px 0}.empty{color:var(--muted);padding:22px 0}</style></head><body><section class="top"><h1>Operations & Moderation</h1><p>Manage one canteen at a time to keep inventory and operating controls separate.</p><form class="selector" method="get"><select name="canteen_id"><option value="0">Select a canteen</option><?php while($c=$canteens->fetch_assoc()):?><option value="<?=$c['id']?>" <?=$selected===$c['id']?'selected':''?>><?=htmlspecialchars($c['canteen_name'])?></option><?php endwhile?></select><button>Open canteen workspace</button></form></section><?php if($message):?><div class="notice"><?=$message?></div><?php endif?><?php if(!$selectedCanteen):?><section class="card empty">Choose a canteen above to manage its operations and food inventory.</section><?php else:?><section class="card"><h2><?=htmlspecialchars($selectedCanteen['canteen_name'])?> operations</h2><p><span class="status <?=$selectedCanteen['is_active']?'open':'closed'?>"><?=$selectedCanteen['is_active']?'Open for orders':'Closed for orders'?></span></p><form method="post"><input type="hidden" name="canteen_id" value="<?=$selected?>"><input type="hidden" name="operating_status" value="<?=$selectedCanteen['is_active']?0:1?>"><button class="save"><?=$selectedCanteen['is_active']?'Close canteen':'Open canteen'?></button></form></section><section class="card"><h2>Food & inventory moderation</h2><p style="color:var(--muted);font-size:13px">Only foods belonging to this canteen are shown.</p><table><thead><tr><th>Food</th><th>Price</th><th>Stock</th><th>Visibility</th><th>Save</th></tr></thead><tbody><?php if($foods&&$foods->num_rows):while($food=$foods->fetch_assoc()):?><tr><form method="post"><input type="hidden" name="canteen_id" value="<?=$selected?>"><input type="hidden" name="food_id" value="<?=$food['id']?>"><td><b><?=htmlspecialchars($food['name'])?></b></td><td>PHP <?=number_format($food['price'],2)?></td><td><input class="stock" type="number" min="0" name="stock_quantity" value="<?=$food['stock_quantity']?>"></td><td><select name="available"><option value="1" <?=$food['is_available']?'selected':''?>>Visible</option><option value="0" <?=$food['is_available']?'':'selected'?>>Hidden</option></select></td><td><button class="save">Save</button></td></form></tr><?php endwhile;else:?><tr><td colspan="5" class="empty">This canteen has no food items.</td></tr><?php endif?></tbody></table></section><?php endif?><section class="card"><h2>Campus announcement</h2><form method="post"><input name="title" placeholder="Announcement title" required><textarea name="message" placeholder="Message for all users" required></textarea><button class="save">Publish announcement</button></form></section></body></html>
